window.AUTH=window.AUTH||{};window.AUTH["24-1260"]={"d":"24-1260","id":"2025/24-1260","n":"Watson v. Republican National Committee","briefs":[{"k":"petitioner","label":"Brief of petitioner Michael Watson","date":"2026-01-02","url":"https://www.supremecourt.gov/DocketPDF/24/24-1260/390664/20260102121935930_No.%2024-1260%20Brief%20for%20Petitioner.pdf","side":"pet","n":39},{"k":"respondent","label":"Brief of respondents Vet Voice Foundation, et al. in support of petitioner","date":"2026-01-02","url":"https://www.supremecourt.gov/DocketPDF/24/24-1260/390707/20260102150216866_24-1260_%20Brief%20for%20Respondents.pdf","side":"res","n":44},{"k":"respondent","label":"Brief of respondents Republican National Committee, et al.","date":"2026-02-09","url":"https://www.supremecourt.gov/DocketPDF/24/24-1260/395791/20260209131726304_Watson%20v.%20RNC%20-%20Red%20Brief.pdf","side":"res","n":46},{"k":"respondent","label":"Brief of respondent Libertarian Party of Mississippi","date":"2026-02-09","url":"https://www.supremecourt.gov/DocketPDF/24/24-1260/395807/20260209143028565_No%2024%201260%20Respondents%20Brief.pdf","side":"res","n":45},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2026-02-17","url":"https://www.supremecourt.gov/DocketPDF/24/24-1260/396427/20260217134927549_24-1260bsacUnitedStates.pdf","side":"us","n":50},{"k":"reply","label":"Reply of petitioner Michael Watson","date":"2026-03-11","url":"https://www.supremecourt.gov/DocketPDF/24/24-1260/400613/20260311151101578_No.%2024-1260%20Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us2r65_g314.pdf","tr":true,"items":[{"t":"case","label":"Burson v. Freeman","cite":"504 U.S. 191","y":1992,"id":"1991/90-1056","sc":1,"sum":"After subjecting Tennessee's statute to exacting scrutiny, since it constituted a facial content-based restriction on political speech in a public forum, the Court held that the statute was narrowly drafted to serve a compelling state interest. By creating a safe zone around polling sites, the statute served the state's interest in protecting its citizen's right to vote freely and effectively.","sumSrc":"Oyez","by":{"0":"13","2":"6","3":"22, 23","4":"16, 27"}},{"t":"case","label":"Campbell v. Whittington","cite":"733 So. 2d 820","y":1999,"court":"Miss.","url":"https://www.courtlistener.com/c/So.%202d/733/820/","by":{"0":"37-38"}},{"t":"case","label":"Chase v. Miller","cite":"41 Pa. 403","y":1862,"url":"https://www.courtlistener.com/c/Pa./41/403/","op":1,"sum":"Declaring that the Pennsylvania Constitution set the “place” of suffrage.","sumSrc":"brief:2","by":{"0":"30, 33","2":"30","3":"18"}},{"t":"case","label":"Democratic National Committee v. Wisconsin State Legislature","cite":"141 S. Ct. 28","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/28/","sc":1,"by":{"0":"2, 28, 38, 47","1":"27","2":"1, 48","3":"46, 47","4":"4, 29-31"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"0":"38, 39"}},{"t":"case","label":"Foster v. Love","cite":"522 U.S. 67","y":1997,"id":"1997/96-670","sc":1,"op":10,"ar":5,"sum":"The Court held that when Louisiana's open primary is applied to select among congressional candidates in October, it conflicts with federal law and to that extent is void. The Court rejected the argument that Louisiana's system only concerns the manner, not the time, of a federal election.","sumSrc":"Oyez","by":{"0":"2-5, 16, 17, 22, 24, 26, 27, 28, 31, 36-39","1":"1, 2, 5, 10–16","2":"i, 2-5, 11, 12, 15, 19, 21, 37, 38","3":"1, 4, 5, 12, 14, 28, 29, 35, 36, 37","4":"2, 4, 7, 15-17","5":"12, 13, 14"}},{"t":"case","label":"Lehman v. McBride","cite":"15 Ohio St. 573","y":1863,"court":"Ohio","url":"https://www.courtlistener.com/c/Ohio%20St./15/573/","sum":"Declaring that the Pennsylvania Constitution set the “place” of suffrage.","sumSrc":"brief:2","by":{"0":"30, 33","2":"30","5":"21"}},{"t":"case","label":"Maddox v. Board of State Canvassers","cite":"149 P.2d 112","y":1944,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/149/112/","op":15,"ar":3,"sum":"Explaining that “states have no power to interfere” with the federal election-day statutes.","sumSrc":"opinion","by":{"0":"28","1":"12, 26","2":"12, 22, 29, 39, 40","3":"29","4":"11, 15","5":"8"}},{"t":"case","label":"Morrison v. Springer","cite":"15 Iowa 304","y":1863,"url":"https://www.courtlistener.com/c/Iowa/15/304/","sum":"Declaring that the Pennsylvania Constitution set the “place” of suffrage.","sumSrc":"brief:2","by":{"0":"29, 30","2":"30"}},{"t":"case","label":"Newberry v. United States","cite":"256 U.S. 232","y":1921,"id":"scdb/1920-108","sc":1,"sum":"1. Section*8 of the “Federal Corrupt Practices Act ” (June 25,,1910, c. 392, 36 Stat. 822; amended August 19, 1911, c. 33, 37 Stat. 25), which undertakes to limit the amount of money which any candidate for the office of Representative in Congress or of United States Senator shall give, contribute, expend, use, or promise, or cause to be given, contributed, expended, used, or promised, in procuring his nomination or …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"1, 16, 24, 25, 36","1":"18","2":"20","3":"8, 21","4":"16"}},{"t":"case","label":"Republican National Committee v. Democratic National Committee","cite":"589 U.S. 423","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/423/","sc":1,"op":1,"sum":"Explaining that a “fundamenta[l]” aspect of an election is ballot “cast[ing],” as distinguished from ballot “recei[pt]”.","sumSrc":"opinion","by":{"0":"2, 19, 27, 28, 36, 37, 42","1":"11, 24","2":"13","3":"43, 44, 45","4":"7, 17","5":"14"}},{"t":"case","label":"Smiley v. Holm","cite":"285 U.S. 355","y":1932,"id":"scdb/1931-045","sc":1,"sum":"1. The function of a state legislature in prescribing the time, place and manner of holding elections for Representatives in Congress under Constitution, Art. 1, § 4, is a law-making function in which the veto power of the state governor participates if, under the state constitution, the governor has that power in the making of state laws.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"State ex rel. Chandler v. Main","cite":"16 Wis. 398","y":1863,"url":"https://www.courtlistener.com/c/Wis./16/398/","sum":"Explaining legislature’s discretion to decide “where the right of suffrage might be exercised” (emphasis added).","sumSrc":"brief:2","by":{"0":"29, 30","2":"30","5":"21"}},{"t":"case","label":"United States v. Classic","cite":"313 U.S. 299","y":1941,"id":"1940-1955/313us299","sc":1,"op":1,"ar":1,"sum":"The majority argued that Newberry was deeply divided over the matter of primaries. He chose instead to rely on logic applied in concurring opinions. Stone rejected the narrow interpretation that Congressional power did not extend to primaries because the framers were unaware of the primary process.","sumSrc":"Oyez","by":{"0":"4, 25","1":"5, 9, 18","5":"8"}},{"t":"case","label":"United States v. Oakland Cannabis Buyers’ Cooperative","cite":"532 U.S. 483","y":2001,"id":"2000/00-151","sc":1,"sum":"The Court held that there is no medical necessity exception to the Controlled Substances Act's prohibitions on manufacturing and distributing marijuana. \"The statute reflects a determination that marijuana has no medical benefits worthy of an exception, \" wrote Justice Thomas, therefore, \"medical necessity is not a defense to manufacturing and distributing marijuana.\" Justice John Paul Stevens' concurring opinion, which was joined by Justices David H. Souter and Ruth Bader Ginsburg, argued that \"[b]ecause necessity was raised in this case as a defense to distribution, the Court need not venture an opinion on whether the defense is available to anyone other than distributors.\" Justice Stephen G. Breyer took no part in the consideration or decision of the case.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Voting Integrity Project, Inc. v. Keisling","cite":"259 F.3d 1169","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/259/1169/","sum":"Rejecting “plaintiffs’ focus on the single act of receiving a ballot from a voter” as “an unnatural and stilted conception of the actions taken by” election officials.","sumSrc":"brief:1","by":{"0":"5, 7","1":"5","2":"5, 8","3":"4","4":"5, 28","5":"14"}},{"t":"const","label":"Article I, Section 4, Clause 1","clauses":[["elections-clause","Elections Clause"]],"text":"The Times, Places and Manner of holding Elections for Senators and Representatives, shall be prescribed in each State by the Legislature thereof; but the Congress may at any time by Law make or alter such Regulations, except as to the Places of chusing Senators.","by":{"0":"5, 46","3":"4"}},{"t":"const","label":"Article II, Section 1, Clause 1","clauses":[["executive-vesting","Executive Vesting Clause"]],"text":"The executive Power shall be vested in a President of the United States of America. He shall hold his Office during the Term of four Years, and, together with the Vice President, chosen for the same Term, be elected, as follows","by":{"0":"5","3":"4"}},{"t":"const","label":"Article II, Section 1, Clause 2","text":"Each State shall appoint, in such Manner as the Legislature thereof may direct, a Number of Electors, equal to the whole Number of Senators and Representatives to which the State may be entitled in the Congress: but no Senator or Representative, or Person holding an Office of Trust or Profit under the United States, shall be appointed an Elector.","by":{"0":"5","3":"4"}},{"t":"const","label":"Article II, Section 1, Clause 4","text":"The Congress may determine the Time of chusing the Electors, and the Day on which they shall give their Votes; which Day shall be the same throughout the United States.","by":{"0":"5, 46","3":"4","4":"4"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"16"}},{"t":"const","label":"Amendment II","clauses":[["second-amendment","Second Amendment"]],"text":"A well regulated Militia, being necessary to the security of a free State, the right of the people to keep and bear Arms, shall not be infringed.","by":{"0":"39"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"16"}},{"t":"const","label":"Amendment XVII","clauses":[["seventeenth-amendment","Seventeenth Amendment"]],"text":"The Senate of the United States shall be composed of two Senators from each State, elected by the people thereof, for six years; and each Senator shall have one vote. The electors in each State shall have the qualifications requisite for electors of the most numerous branch of the State legislatures. When vacancies happen in the representation of any State in the Senate, the executive authority of such State shall issue writs of election to fill such vacancies: Provided, That the legislature of any State may empower the executive thereof to make temporary appointments until the people fill the vacancies by election as the legislature may direct. This amendment shall not be so construed as to affect the election or term of any Senator chosen before it becomes valid as part of the Constitution.","by":{"0":"8","4":"5"}},{"t":"const","label":"Amendment XX","by":{"0":"46"}},{"t":"usc","label":"2 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/2/1","stext":{"head":"§1. Time for election of Senators","paras":[[0,"At the regular election held in any State next preceding the expiration of the term for which any Senator was elected to represent such State in Congress, at which election a Representative to Congress is regularly by law to be chosen, a United States Senator from said State shall be elected by the people thereof for the term commencing on the 3d day of January next thereafter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/1?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1. Time for election of Senators","tname":"The Congress","by":{"0":"i, 1, 5, 9, 17, 24, 26, 36, 46","1":"1, 17, 47","2":"i, 1, 4, 18, 19","3":"1, 11, 13, 14","4":"1, 2, 5, 8, 14","5":"2"}},{"t":"usc","label":"2 U.S.C. § 7","url":"https://www.law.cornell.edu/uscode/text/2/7","stext":{"head":"§7. Time of election","paras":[[0,"The Tuesday next after the 1st Monday in November, in every even numbered year, is established as the day for the election, in each of the States and Territories of the United States, of Representatives and Delegates to the Congress commencing on the 3d day of January next thereafter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/7?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7. Time of election","tname":"The Congress","by":{"0":"i, 1, 5, 8, 17, 24, 26, 36, 46","1":"1, 4, 10, 16, 35, 47","2":"i, 1, 4, 14, 18, 19, 47","3":"1, 6, 11, 13, 14, 31","4":"1, 2, 5, 8, 14","5":"2"}},{"t":"usc","label":"2 U.S.C. § 8","url":"https://www.law.cornell.edu/uscode/text/2/8","stext":{"head":"§8. Vacancies","paras":[[0,"(a) In general"],[0,"Except as provided in subsection (b), the time for holding elections in any State, District, or Territory for a Representative or Delegate to fill a vacancy, whether such vacancy is caused by a failure to elect at the time prescribed by law, or by the death, resignation, or incapacity of a person elected, may be prescribed by the laws of the several States and Territories respectively."],[0,"(b) Special rules in extraordinary circumstances"],[0,"(1) In general"],[1,"In extraordinary circumstances, the executive authority of any State in which a vacancy exists in its representation in the House of Representatives shall issue a writ of election to fill such vacancy by special election."],[0,"(2) Timing of special election"],[1,"A special election held under this subsection to fill a vacancy shall take place not later than 49 days after the Speaker of the House of Representatives announces that the vacancy exists, unless, during the 75-day period which begins on the date of the announcement of the vacancy—"],[2,"(A) a regularly scheduled general election for the office involved is to be held; or"],[2,"(B) another special election for the office involved is to be held, pursuant to a writ for a special election issued by the chief executive of the State prior to the date of the announcement of the vacancy."],[0,"(3) Nominations by parties"],[1,"If a special election is to be held under this subsection, the determination of the candidates who will run in such election shall be made—"],[2,"(A) by nominations made not later than 10 days after the Speaker announces that the vacancy exists by the political parties of the State that are authorized by State law to nominate candidates for the election; or"],[2,"(B) by any other method the State considers appropriate, including holding primary elections, that will ensure that the State will hold the special election within the deadline required under paragraph (2)."],[0,"(4) Extraordinary circumstances"],[0,"(A) In general"],[2,"In this subsection, \"extraordinary circumstances\" occur when the Speaker of the House of Representatives announces that vacancies in the representation from the States in the House exceed 100."],[0,"(B) Judicial review"],[2,"If any action is brought for declaratory or injunctive relief to challenge an announcement made under subparagraph (A), the following rules shall apply:"],[3,"(i) Not later than 2 days after the announcement, the action shall be filed in the United States District Court having jurisdiction in the district of the Member of the House of Representatives whose seat has been announced to be vacant and shall be heard by a 3-judge court convened pursuant to section 2284 of title 28."],[3,"(ii) A copy of the complaint shall be delivered promptly to the Clerk of the House of Representatives."],[3,"(iii) A final decision in the action shall be made within 3 days of the filing of such action and shall not be reviewable."],[3,"(iv) The executive authority of the State that contains the district of the Member of the House of Representatives whose seat has been announced to be vacant shall have the right to intervene either in support of or opposition to the position of a party to the case regarding the announcement of such vacancy."],[0,"(5) Protecting ability of absent military and overseas voters to participate in special elections"],[0,"(A) Deadline for transmittal of absentee ballots"],[2,"In conducting a special election held under this subsection to fill a vacancy in its representation, the State shall ensure to the greatest extent practicable (including through the use of electronic means) that absentee ballots for the election are transmitted to absent uniformed services voters and overseas voters (as such terms are defined in the Uniformed and Overseas Citizens Absentee Voting Act [52 U.S.C. 20301 et seq.]) not later than 15 days after the Speaker of the House of Representatives announces that the vacancy exists."],[0,"(B) Period for ballot transit time"],[2,"Notwithstanding the deadlines referred to in paragraphs (2) and (3), in the case of an individual who is an absent uniformed services voter or an overseas voter (as such terms are defined in the Uniformed and Overseas Citizens Absentee Voting Act), a State shall accept and process any otherwise valid ballot or other election material from the voter so long as the ballot or other material is received by the appropriate State election official not later than 45 days after the State transmits the ballot or other material to the voter."],[0,"(6) Application to District of Columbia and territories"],[1,"This subsection shall apply—"],[2,"(A) to a Delegate or Resident Commissioner to the Congress in the same manner as it applies to a Member of the House of Representatives; and"],[2,"(B) to the District of Columbia, the Commonwealth of Puerto Rico, American Samoa, Guam, and the United States Virgin Islands in the same manner as it applies to a State, except that a vacancy in the representation from any such jurisdiction in the House shall not be taken into account by the Speaker in determining whether vacancies in the representation from the States in the House exceed 100 for purposes of paragraph (4)(A)."],[0,"(7) Rule of construction regarding Federal election laws"],[1,"Nothing in this subsection may be construed to affect the application to special elections under this subsection of any Federal law governing the administration of elections for Federal office (including any law providing for the enforcement of any such law), including, but not limited to, the following:"],[2,"(A) The Voting Rights Act of 1965 (42 U.S.C. 1973 et seq.) [now 52 U.S.C. 10301 et seq.], as amended."],[2,"(B) The Voting Accessibility for the Elderly and Handicapped Act (42 U.S.C. 1973ee et seq.) [now 52 U.S.C. 20101 et seq.], as amended."],[2,"(C) The Uniformed and Overseas Citizens Absentee Voting Act (42 U.S.C. 1973ff et seq.) [now 52 U.S.C. 20301 et seq.], as amended."],[2,"(D) The National Voter Registration Act of 1993 (42 U.S.C. 1973gg et seq.) [now 52 U.S.C. 20501 et seq.], as amended."],[2,"(E) The Americans With Disabilities Act of 1990 (42 U.S.C. 12101 et seq.), as amended."],[2,"(F) The Rehabilitation Act of 1973 (29 U.S.C. 701 et seq.), as amended."],[2,"(G) The Help America Vote Act of 2002 (42 U.S.C. 15301 et seq.) [now 52 U.S.C. 20901 et seq.], as amended."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/8?type=usc&year=mostrecent&link-type=html"},"head":"§8. Vacancies","tname":"The Congress","by":{"0":"21, 45","2":"5, 19, 21"}},{"t":"usc","label":"3 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/3/1","subs":["(1948)"],"stext":{"head":"§1. Time of appointing electors","paras":[[0,"The electors of President and Vice President shall be appointed, in each State, on election day, in accordance with the laws of the State enacted prior to election day."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/3/1?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1. Time of appointing electors","tname":"The President","by":{"0":"i, 1, 5, 7, 24, 36, 45","1":"1, 4, 17, 18, 23, 32, 35, 47, 50","2":"i, 1, 4, 18","3":"1, 11, 13, 14, 5","4":"1, 2, 5, 15","5":"2, 20"}},{"t":"usc","label":"3 U.S.C. § 5","url":"https://www.law.cornell.edu/uscode/text/3/5","by":{"0":"46"}},{"t":"usc","label":"3 U.S.C. § 7","url":"https://www.law.cornell.edu/uscode/text/3/7","stext":{"head":"§7. Meeting and vote of electors","paras":[[0,"The electors of President and Vice President of each State shall meet and give their votes on the first Tuesday after the second Wednesday in December next following their appointment at such place in each State in accordance with the laws of the State enacted prior to election day."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/3/7?type=usc&year=mostrecent&link-type=html"},"head":"§7. Meeting and vote of electors","tname":"The President","by":{"0":"46","5":"20"}},{"t":"usc","label":"3 U.S.C. § 21","url":"https://www.law.cornell.edu/uscode/text/3/21","subs":["(1)"],"stext":{"head":"§21. Definitions","paras":[[0,"As used in this chapter the term—"],[1,"(1) \"election day\" means the Tuesday next after the first Monday in November, in every fourth year succeeding every election of a President and Vice President held in each State, except, in the case of a State that appoints electors by popular vote, if the State modifies the period of voting, as necessitated by force majeure events that are extraordinary and catastrophic, as provided under laws of the State enacted prior to such day, \"election day\" shall include the modified period of voting."],[1,"(2) \"State\" includes the District of Columbia."],[1,"(3) \"executive\" means, with respect to any State, the Governor of the State (or, in the case of the District of Columbia, the Mayor of the District of Columbia), except when the laws or constitution of a State in effect as of election day expressly require a different State executive to perform the duties identified under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/3/21?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§21. Definitions","tname":"The President","by":{"0":"7, 21, 45","1":"1, 4, 17","2":"4, 5, 20","4":"1, 5, 8, 15","5":"20"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"4"}},{"t":"usc","label":"52 U.S.C. § 10502","url":"https://www.law.cornell.edu/uscode/text/52/10502","subs":["(d)","(g)"],"stext":{"head":"§10502. Residence requirements for voting","paras":[[0,"(a) Congressional findings"],[0,"The Congress hereby finds that the imposition and application of the durational residency requirement as a precondition to voting for the offices of President and Vice President, and the lack of sufficient opportunities for absentee registration and absentee balloting in presidential elections—"],[1,"(1) denies or abridges the inherent constitutional right of citizens to vote for their President and Vice President;"],[1,"(2) denies or abridges the inherent constitutional right of citizens to enjoy their free movement across State lines;"],[1,"(3) denies or abridges the privileges and immunities guaranteed to the citizens of each State under article IV, section 2, clause 1, of the Constitution;"],[1,"(4) in some instances has the impermissible purpose or effect of denying citizens the right to vote for such officers because of the way they may vote;"],[1,"(5) has the effect of denying to citizens the equality of civil rights, and due process and equal protection of the laws that are guaranteed to them under the fourteenth amendment; and"],[1,"(6) does not bear a reasonable relationship to any compelling State interest in the conduct of presidential elections."],[0,"(b) Congressional declaration: durational residency requirement, abolishment; absentee registration and balloting standards, establishment"],[0,"Upon the basis of these findings, Congress declares that in order to secure and protect the above-stated rights of citizens under the Constitution, to enable citizens to better obtain the enjoyment of such rights, and to enforce the guarantees of the fourteenth amendment, it is necessary (1) to completely abolish the durational residency requirement as a precondition to voting for President and Vice President, and (2) to establish nationwide, uniform standards relative to absentee registration and absentee balloting in presidential elections."],[0,"(c) Prohibition of denial of right to vote because of durational residency requirement or absentee balloting"],[0,"No citizen of the United States who is otherwise qualified to vote in any election for President and Vice President shall be denied the right to vote for electors for President and Vice President, or for President and Vice President, in such election because of the failure of such citizen to comply with any durational residency requirement of such State or political subdivision; nor shall any citizen of the United States be denied the right to vote for electors for President and Vice President, or for President and Vice President, in such election because of the failure of such citizen to be physically present in such State or political subdivision at the time of such election, if such citizen shall have complied with the requirements prescribed by the law of such State or political subdivision providing for the casting of absentee ballots in such election."],[0,"(d) Registration: time for application; absentee balloting: time of application and return of ballots"],[0,"For the purposes of this section, each State shall provide by law for the registration or other means of qualification of all duly qualified residents of such State who apply, not later than thirty days immediately prior to any presidential election, for registration or qualification to vote for the choice of electors for President and Vice President or for President and Vice President in such election; and each State shall provide by law for the casting of absentee ballots for the choice of electors for President and Vice President, or for President and Vice President, by all duly qualified residents of such State who may be absent from their election district or unit in such State on the day such election is held and who have applied therefor not later than seven days immediately prior to such election and have returned such ballots to the appropriate election official of such State not later than the time of closing of the polls in such State on the day of such election."],[0,"(e) Change of residence; voting in person or by absentee ballot in State of prior residence"],[0,"If any citizen of the United States who is otherwise qualified to vote in any State or political subdivision in any election for President and Vice President has begun residence in such State or political subdivision after the thirtieth day next preceding such election and, for that reason, does not satisfy the registration requirements of such State or political subdivision he shall be allowed to vote for the choice of electors for President and Vice President, or for President and Vice President, in such election, (1) in person in the State or political subdivision in which he resided immediately prior to his removal if he had satisfied, as of the date of his change of residence, the requirements to vote in that State or political subdivision, or (2) by absentee ballot in the State or political subdivision in which he resided immediately prior to his removal if he satisfies, but for his nonresident status and the reason for his absence, the requirements for absentee voting in that State or political subdivision."],[0,"(f) Absentee registration requirement"],[0,"No citizen of the United States who is otherwise qualified to vote by absentee ballot in any State or political subdivision in any election for President and Vice President shall be denied the right to vote for the choice of electors for President and Vice President, or for President and Vice President, in such election because of any requirement of registration that does not include a provision for absentee registration."],[0,"(g) State or local adoption of less restrictive voting practices"],[0,"Nothing in this section shall prevent any State or political subdivision from adopting less restrictive voting practices than those that are prescribed herein."],[0,"(h) \"State\" defined"],[0,"The term \"State\" as used in this section includes each of the several States and the District of Columbia."],[0,"(i) False registration, and other fraudulent acts and conspiracies: application of penalty for false information in registering or voting"],[0,"The provisions of section 10307(c) of this title shall apply to false registration, and other fraudulent acts and conspiracies, committed under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10502?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§10502. Residence requirements for voting","tname":"Voting and Elections","by":{"0":"10, 20","1":"44","2":"42","4":"26, 26, 26"}},{"t":"usc","label":"52 U.S.C. § 20301","url":"https://www.law.cornell.edu/uscode/text/52/20301","stext":{"head":"§20301. Federal responsibilities","paras":[[0,"(a) Presidential designee"],[0,"The President shall designate the head of an executive department to have primary responsibility for Federal functions under this chapter."],[0,"(b) Duties of Presidential designee"],[0,"The Presidential designee shall—"],[1,"(1) consult State and local election officials in carrying out this chapter, and ensure that such officials are aware of the requirements of this Act;"],[1,"(2) prescribe an official post card form, containing both an absentee voter registration application and an absentee ballot application, for use by the States as required under section 20302(a)(4) of this title;"],[1,"(3) carry out section 20303 of this title with respect to the Federal write-in absentee ballot for absent uniformed services voters and overseas voters in general elections for Federal office;"],[1,"(4) prescribe a suggested design for absentee ballot mailing envelopes;"],[1,"(5) compile and distribute (A) descriptive material on State absentee registration and voting procedures, and (B) to the extent practicable, facts relating to specific elections, including dates, offices involved, and the text of ballot questions;"],[1,"(6) not later than the end of each year after a Presidential election year, transmit to the President and the Congress a report on the effectiveness of assistance under this chapter, including a statistical analysis of uniformed services voter participation, a separate statistical analysis of overseas nonmilitary participation, and a description of State-Federal cooperation;"],[1,"(7) prescribe a standard oath for use with any document under this chapter affirming that a material misstatement of fact in the completion of such a document may constitute grounds for a conviction for perjury;"],[1,"(8) carry out section 20304 of this title with respect to the collection and delivery of marked absentee ballots of absent overseas uniformed services voters in elections for Federal office;"],[1,"(9) to the greatest extent practicable, take such actions as may be necessary—"],[2,"(A) to ensure that absent uniformed services voters who cast absentee ballots at locations or facilities under the jurisdiction of the Presidential designee are able to do so in a private and independent manner; and"],[2,"(B) to protect the privacy of the contents of absentee ballots cast by absentee uniformed services voters and overseas voters while such ballots are in the possession or control of the Presidential designee;"],[1,"(10) carry out section 20305 of this title with respect to Federal Voting Assistance Program Improvements; and"],[1,"(11) working with the Election Assistance Commission and the chief State election official of each State, develop standards—"],[2,"(A) for States to report data on the number of absentee ballots transmitted and received under section 20302(c) of this title and such other data as the Presidential designee determines appropriate; and"],[2,"(B) for the Presidential designee to store the data reported."],[0,"(c) Duties of other Federal officials"],[0,"(1) In general"],[1,"The head of each Government department, agency, or other entity shall, upon request of the Presidential designee, distribute balloting materials and otherwise cooperate in carrying out this chapter."],[0,"(2) Administrator of General Services"],[1,"As directed by the Presidential designee, the Administrator of General Services shall furnish official post card forms (prescribed under subsection (b)) and Federal write-in absentee ballots (prescribed under section 20303 of this title)."],[0,"(d) Authorization of appropriations for carrying out Federal Voting Assistance Program Improvements"],[0,"There are authorized to be appropriated to the Presidential designee such sums as are necessary for purposes of carrying out subsection (b)(10)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20301?type=usc&year=mostrecent&link-type=html"},"head":"§20301. Federal responsibilities","tname":"Voting and Elections","by":{"0":"20","4":"23"}},{"t":"usc","label":"52 U.S.C. § 20302","url":"https://www.law.cornell.edu/uscode/text/52/20302","stext":{"head":"§20302. State responsibilities","paras":[[0,"(a) In general"],[0,"Each State shall—"],[1,"(1) permit absent uniformed services voters and overseas voters to use absentee registration procedures and to vote by absentee ballot in general, special, primary, and runoff elections for Federal office;"],[1,"(2) accept and process, with respect to any election for Federal office, any otherwise valid voter registration application and absentee ballot application from an absent uniformed services voter or overseas voter, if the application is received by the appropriate State election official not less than 30 days before the election;"],[1,"(3) permit absent uniformed services voters and overseas voters to use Federal write-in absentee ballots (in accordance with section 20303 of this title) in general elections for Federal office;"],[1,"(4) use the official post card form (prescribed under section 20301 of this title) for simultaneous voter registration application and absentee ballot application;"],[1,"(5) if the State requires an oath or affirmation to accompany any document under this chapter, use the standard oath prescribed by the Presidential designee under section 20301(b)(7) of this title;"],[1,"(6) in addition to any other method of registering to vote or applying for an absentee ballot in the State, establish procedures—"],[2,"(A) for absent uniformed services voters and overseas voters to request by mail and electronically voter registration applications and absentee ballot applications with respect to general, special, primary, and runoff elections for Federal office in accordance with subsection (e);"],[2,"(B) for States to send by mail and electronically (in accordance with the preferred method of transmission designated by the absent uniformed services voter or overseas voter under subparagraph (C)) voter registration applications and absentee ballot applications requested under subparagraph (A) in accordance with subsection (e); and"],[2,"(C) by which the absent uniformed services voter or overseas voter can designate whether the voter prefers that such voter registration application or absentee ballot application be transmitted by mail or electronically;"],[1,"(7) in addition to any other method of transmitting blank absentee ballots in the State, establish procedures for transmitting by mail and electronically blank absentee ballots to absent uniformed services voters and overseas voters with respect to general, special, primary, and runoff elections for Federal office in accordance with subsection (f);"],[1,"(8) transmit a validly requested absentee ballot to an absent uniformed services voter or overseas voter—"],[2,"(A) except as provided in subsection (g), in the case in which the request is received at least 45 days before an election for Federal office, not later than 45 days before the election; and"],[2,"(B) in the case in which the request is received less than 45 days before an election for Federal office—"],[3,"(i) in accordance with State law; and"],[3,"(ii) if practicable and as determined appropriate by the State, in a manner that expedites the transmission of such absentee ballot;"],[1,"(9) if the State declares or otherwise holds a runoff election for Federal office, establish a written plan that provides absentee ballots are made available to absent uniformed services voters and overseas voters in manner 1 that gives them sufficient time to vote in the runoff election;"],[1,"(10) carry out section 20304(b)(1) of this title with respect to the processing and acceptance of marked absentee ballots of absent overseas uniformed services voters; and"],[1,"(11) report data on the number of absentee ballots transmitted and received under subsection (c) and such other data as the Presidential designee determines appropriate in accordance with the standards developed by the Presidential designee under section 20301(b)(11) of this title."],[0,"(b) Designation of single State office to provide information on registration and absentee ballot procedures for all voters in State"],[0,"(1) In general"],[1,"Each State shall designate a single office which shall be responsible for providing information regarding voter registration procedures and absentee ballot procedures to be used by absent uniformed services voters and overseas voters with respect to elections for Federal office (including procedures relating to the use of the Federal write-in absentee ballot) to all absent uniformed services voters and overseas voters who wish to register to vote or vote in any jurisdiction in the State."],[0,"(2) Recommendation regarding use of office to accept and process materials"],[1,"Congress recommends that the State office designated under paragraph (1) be responsible for carrying out the State's duties under this Act, including accepting valid voter registration applications, absentee ballot applications, and absentee ballots (including Federal write-in absentee ballots) from all absent uniformed services voters and overseas voters who wish to register to vote or vote in any jurisdiction in the State."],[0,"(c) Report on number of absentee ballots transmitted and received"],[0,"Not later than 90 days after the date of each regularly scheduled general election for Federal office, each State and unit of local government which administered the election shall (through the State, in the case of a unit of local government) submit a report to the Election Assistance Commission (established under the Help America Vote Act of 2002 [52 U.S.C. 20901 et seq.]) on the combined number of absentee ballots transmitted to absent uniformed services voters and overseas voters for the election and the combined number of such ballots which were returned by such voters and cast in the election, and shall make such report available to the general public."],[0,"(d) Registration notification"],[0,"With respect to each absent uniformed services voter and each overseas voter who submits a voter registration application or an absentee ballot request, if the State rejects the application or request, the State shall provide the voter with the reasons for the rejection."],[0,"(e) Designation of means of electronic communication for absent uniformed services voters and overseas voters to request and for States to send voter registration applications and absentee ballot applications, and for other purposes related to voting information"],[0,"(1) In general"],[1,"Each State shall, in addition to the designation of a single State office under subsection (b), designate not less than 1 means of electronic communication—"],[2,"(A) for use by absent uniformed services voters and overseas voters who wish to register to vote or vote in any jurisdiction in the State to request voter registration applications and absentee ballot applications under subsection (a)(6);"],[2,"(B) for use by States to send voter registration applications and absentee ballot applications requested under such subsection; and"],[2,"(C) for the purpose of providing related voting, balloting, and election information to absent uniformed services voters and overseas voters."],[0,"(2) Clarification regarding provision of multiple means of electronic communication"],[1,"A State may, in addition to the means of electronic communication so designated, provide multiple means of electronic communication to absent uniformed services voters and overseas voters, including a means of electronic communication for the appropriate jurisdiction of the State."],[0,"(3) Inclusion of designated means of electronic communication with informational and instructional materials that accompany balloting materials"],[1,"Each State shall include a means of electronic communication so designated with all informational and instructional materials that accompany balloting materials sent by the State to absent uniformed services voters and overseas voters."],[0,"(4) Availability and maintenance of online repository of State contact information"],[1,"The Federal Voting Assistance Program of the Department of Defense shall maintain and make available to the public an online repository of State contact information with respect to elections for Federal office, including the single State office designated under subsection (b) and the means of electronic communication designated under paragraph (1), to be used by absent uniformed services voters and overseas voters as a resource to send voter registration applications and absentee ballot applications to the appropriate jurisdiction in the State."],[0,"(5) Transmission if no preference indicated"],[1,"In the case where an absent uniformed services voter or overseas voter does not designate a preference under subsection (a)(6)(C), the State shall transmit the voter registration application or absentee ballot application by any delivery method allowable in accordance with applicable State law, or if there is no applicable State law, by mail."],[0,"(6) Security and privacy protections"],[0,"(A) Security protections"],[2,"To the extent practicable, States shall ensure that the procedures established under subsection (a)(6) protect the security and integrity of the voter registration and absentee ballot application request processes."],[0,"(B) Privacy protections"],[2,"To the extent practicable, the procedures established under subsection (a)(6) shall ensure that the privacy of the identity and other personal data of an absent uniformed services voter or overseas voter who requests or is sent a voter registration application or absentee ballot application under such subsection is protected throughout the process of making such request or being sent such application."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20302?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§20302. State responsibilities","tname":"Voting and Elections","by":{"0":"10","2":"46"}},{"t":"usc","label":"52 U.S.C. § 20307","url":"https://www.law.cornell.edu/uscode/text/52/20307","stext":{"head":"§20307. Enforcement","paras":[[0,"(a) In general"],[0,"The Attorney General may bring a civil action in an appropriate district court for such declaratory or injunctive relief as may be necessary to carry out this chapter."],[0,"(b) Report to Congress"],[0,"Not later than December 31 of each year, the Attorney General shall submit to Congress an annual report on any civil action brought under subsection (a) during the preceding year."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20307?type=usc&year=mostrecent&link-type=html"},"head":"§20307. Enforcement","tname":"Voting and Elections","by":{"0":"21, 44","1":"48, 49"}},{"t":"usc","label":"52 U.S.C. § 20901","url":"https://www.law.cornell.edu/uscode/text/52/20901","stext":{"head":"§20901. Payments to States for activities to improve administration of elections","paras":[[0,"(a) In general"],[0,"Not later than 45 days after October 29, 2002, the Administrator of General Services (in this subchapter referred to as the \"Administrator\") shall establish a program under which the Administrator shall make a payment to each State in which the chief executive officer of the State, or designee, in consultation and coordination with the chief State election official, notifies the Administrator not later than 6 months after October 29, 2002, that the State intends to use the payment in accordance with this section."],[0,"(b) Use of payment"],[0,"(1) In general"],[1,"A State shall use the funds provided under a payment made under this section to carry out one or more of the following activities:"],[2,"(A) Complying with the requirements under subchapter III."],[2,"(B) Improving the administration of elections for Federal office."],[2,"(C) Educating voters concerning voting procedures, voting rights, and voting technology."],[2,"(D) Training election officials, poll workers, and election volunteers."],[2,"(E) Developing the State plan for requirements payments to be submitted under subpart 1 of part D of subchapter II."],[2,"(F) Improving, acquiring, leasing, modifying, or replacing voting systems and technology and methods for casting and counting votes."],[2,"(G) Improving the accessibility and quantity of polling places, including providing physical access for individuals with disabilities, providing nonvisual access for individuals with visual impairments, and providing assistance to Native Americans, Alaska Native citizens, and to individuals with limited proficiency in the English language."],[2,"(H) Establishing toll-free telephone hotlines that voters may use to report possible voting fraud and voting rights violations, to obtain general election information, and to access detailed automated information on their own voter registration status, specific polling place locations, and other relevant information."],[0,"(2) Limitation"],[1,"A State may not use the funds provided under a payment made under this section—"],[2,"(A) to pay costs associated with any litigation, except to the extent that such costs otherwise constitute permitted uses of a payment under this section; or"],[2,"(B) for the payment of any judgment."],[0,"(c) Use of funds to be consistent with other laws and requirements"],[0,"In order to receive a payment under the program under this section, the State shall provide the Administrator with certifications that—"],[1,"(1) the State will use the funds provided under the payment in a manner that is consistent with each of the laws described in section 21145 of this title, as such laws relate to the provisions of this chapter; and"],[1,"(2) the proposed uses of the funds are not inconsistent with the requirements of subchapter III."],[0,"(d) Amount of payment"],[0,"(1) In general"],[1,"Subject to section 20903(b) of this title, the amount of payment made to a State under this section shall be the minimum payment amount described in paragraph (2) plus the voting age population proportion amount described in paragraph (3)."],[0,"(2) Minimum payment amount"],[1,"The minimum payment amount described in this paragraph is—"],[2,"(A) in the case of any of the several States or the District of Columbia, one-half of 1 percent of the aggregate amount made available for payments under this section; and"],[2,"(B) in the case of the Commonwealth of Puerto Rico, Guam, American Samoa, or the United States Virgin Islands, one-tenth of 1 percent of such aggregate amount."],[0,"(3) Voting age population proportion amount"],[1,"The voting age population proportion amount described in this paragraph is the product of—"],[2,"(A) the aggregate amount made available for payments under this section minus the total of all of the minimum payment amounts determined under paragraph (2); and"],[2,"(B) the voting age population proportion for the State (as defined in paragraph (4))."],[0,"(4) Voting age population proportion defined"],[1,"The term \"voting age population proportion\" means, with respect to a State, the amount equal to the quotient of—"],[2,"(A) the voting age population of the State (as reported in the most recent decennial census); and"],[2,"(B) the total voting age population of all States (as reported in the most recent decennial census)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20901?type=usc&year=mostrecent&link-type=html"},"head":"§20901. Payments to States for activities to improve administration of elections","tname":"Voting and Elections","by":{"0":"20-21","4":"26"}},{"t":"usc","label":"52 U.S.C. § 21082","url":"https://www.law.cornell.edu/uscode/text/52/21082","subs":["(a)"],"stext":{"head":"§21082. Provisional voting and voting information requirements","paras":[[0,"(a) Provisional voting requirements"],[0,"If an individual declares that such individual is a registered voter in the jurisdiction in which the individual desires to vote and that the individual is eligible to vote in an election for Federal office, but the name of the individual does not appear on the official list of eligible voters for the polling place or an election official asserts that the individual is not eligible to vote, such individual shall be permitted to cast a provisional ballot as follows:"],[1,"(1) An election official at the polling place shall notify the individual that the individual may cast a provisional ballot in that election."],[1,"(2) The individual shall be permitted to cast a provisional ballot at that polling place upon the execution of a written affirmation by the individual before an election official at the polling place stating that the individual is—"],[2,"(A) a registered voter in the jurisdiction in which the individual desires to vote; and"],[2,"(B) eligible to vote in that election."],[1,"(3) An election official at the polling place shall transmit the ballot cast by the individual or the voter information contained in the written affirmation executed by the individual under paragraph (2) to an appropriate State or local election official for prompt verification under paragraph (4)."],[1,"(4) If the appropriate State or local election official to whom the ballot or voter information is transmitted under paragraph (3) determines that the individual is eligible under State law to vote, the individual's provisional ballot shall be counted as a vote in that election in accordance with State law."],[1,"(5)(A) At the time that an individual casts a provisional ballot, the appropriate State or local election official shall give the individual written information that states that any individual who casts a provisional ballot will be able to ascertain under the system established under subparagraph (B) whether the vote was counted, and, if the vote was not counted, the reason that the vote was not counted."],[1,"(B) The appropriate State or local election official shall establish a free access system (such as a toll-free telephone number or an Internet website) that any individual who casts a provisional ballot may access to discover whether the vote of that individual was counted, and, if the vote was not counted, the reason that the vote was not counted."],[0,"States described in section 20503(b) of this title may meet the requirements of this subsection using voter registration procedures established under applicable State law. The appropriate State or local official shall establish and maintain reasonable procedures necessary to protect the security, confidentiality, and integrity of personal information collected, stored, or otherwise used by the free access system established under paragraph (5)(B). Access to information about an individual provisional ballot shall be restricted to the individual who cast the ballot."],[0,"(b) Voting information requirements"],[0,"(1) Public posting on election day"],[1,"The appropriate State or local election official shall cause voting information to be publicly posted at each polling place on the day of each election for Federal office."],[0,"(2) Voting information defined"],[1,"In this section, the term \"voting information\" means—"],[2,"(A) a sample version of the ballot that will be used for that election;"],[2,"(B) information regarding the date of the election and the hours during which polling places will be open;"],[2,"(C) instructions on how to vote, including how to cast a vote and how to cast a provisional ballot;"],[2,"(D) instructions for mail-in registrants and first-time voters under section 21083(b) of this title;"],[2,"(E) general information on voting rights under applicable Federal and State laws, including information on the right of an individual to cast a provisional ballot and instructions on how to contact the appropriate officials if these rights are alleged to have been violated; and"],[2,"(F) general information on Federal and State laws regarding prohibitions on acts of fraud and misrepresentation."],[0,"(c) Voters who vote after the polls close"],[0,"Any individual who votes in an election for Federal office as a result of a Federal or State court order or any other order extending the time established for closing the polls by a State law in effect 10 days before the date of that election may only vote in that election by casting a provisional ballot under subsection (a). Any such ballot cast under the preceding sentence shall be separated and held apart from other provisional ballots cast by those not affected by the order."],[0,"(d) Effective date for provisional voting and voting information"],[0,"Each State and jurisdiction shall be required to comply with the requirements of this section on and after January 1, 2004."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/21082?type=usc&year=mostrecent&link-type=html"},"head":"§21082. Provisional voting and voting information requirements","tname":"Voting and Elections","by":{"0":"21, 44","1":"49","2":"44","4":"27"}},{"t":"case","label":"Arizona v. Inter Tribal Council of Ariz., Inc.","cite":"570 U.S. 1","y":2013,"id":"2012/12-71","sc":1,"ar":1,"sum":"The Court found the National Voter Registration Act preempted other voter registration requirements.","sumSrc":"Oyez","by":{"1":"10, 15, 19–20","2":"4, 18","3":"6, 13, 31, 38","4":"8"}},{"t":"case","label":"Bilski v. Kappos","cite":"561 U.S. 593","y":2010,"id":"2009/08-964","sc":1,"sum":"The Court held that the \"machine-or-transformation\" test adopted by the Patent and Trademark Office (PTO) was a legal means for determining patent eligibility.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"op":4,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"1":"49","2":"42"}},{"t":"case","label":"Burke v. State Bd. of Canvassers","cite":"107 P.2d 773","y":1940,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/107/773/","by":{"1":"27","4":"18"}},{"t":"case","label":"Bush v. Gore","cite":"531 U.S. 98","y":2000,"id":"2000/00-949","sc":1,"sum":"The Court found that the Florida government violated the Equal Protection Clause in ordering a partial recount of the 2000 presidential election ballots.","sumSrc":"Oyez","by":{"1":"5, 23"}},{"t":"case","label":"California v. FERC","cite":"495 U.S. 490","y":1990,"id":"1989/89-333","sc":1,"op":1,"sum":"The California requirements for minimum stream flows cannot be given effect and allowed to supplement the federal flow requirements.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"CSX Transp., Inc. v. Easterwood","cite":"507 U.S. 658","y":1993,"id":"1992/91-790","sc":1,"sum":"Under the FRSA, federal regulations adopted by the Secretary of Transportation pre-empt Easterwood's negligence action only insofar as it asserts that CSX's train was traveling at an excessive speed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Eakin v. Adams Cnty. Bd. of Elections","cite":"149 F.4th 291","y":2025,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/149/291/","by":{"1":"37"}},{"t":"case","label":"Elliott v. Hogan","cite":"315 S.W.2d 840","y":1958,"court":"Mo. App.","url":"https://www.courtlistener.com/c/S.W.2d/315/840/","by":{"1":"43"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"50","4":"25"}},{"t":"case","label":"Goodell v. Judith Basin County","cite":"224 P. 1110","y":1924,"court":"Mont.","url":"https://www.courtlistener.com/c/P./224/1110/","op":1,"sum":"Noting that whatever other state courts have decided under their laws, this case turns on “our state Constitution”.","sumSrc":"brief:5","by":{"1":"26","4":"10","5":"8"}},{"t":"case","label":"Hammond v. Hickel","cite":"588 P.2d 256","y":1978,"court":"Alaska","url":"https://www.courtlistener.com/c/P.2d/588/256/","by":{"1":"43"}},{"t":"case","label":"Harris v. Fla. Elections Canvassing Comm’n","cite":"122 F. Supp. 2d 1317","y":2000,"court":"N.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/122/1317/","sum":"Holding that Congress, in enacting 3 U.S.C. § 1 “certainly did not intend to disenfranchise voters whose only reason for not being able to have their ballots arrive by the close of election day is that they were serving their country overseas”.","sumSrc":"brief:1","by":{"1":"3, 23–24, 32, 50","2":"39","4":"24, 25"}},{"t":"case","label":"INS v. Pangilinan","cite":"486 U.S. 875","y":1988,"id":"1987/86-1992","sc":1,"sum":"Respondents, 16 Filipino nationals who served with the United States Armed Forces during World War II, seek United States citizenship pursuant to §§ 701 through 705 of the Nationality Act of 1940, as amended in 1942. Under § 702 of the Act, the Commissioner of Immigration and Naturalization was authorized to designate representatives to receive petitions, conduct hearings, and grant naturalization outside the United …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Jama v. Immigr. & Customs Enf’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Kansas v. Garcia","cite":"589 U.S. 191","y":2020,"id":"2019/17-834","sc":1,"op":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"1":"11, 20"}},{"t":"case","label":"Millsaps v. Thompson","cite":"259 F.3d 535","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/259/535/","sum":"Rejecting “plaintiffs’ focus on the single act of receiving a ballot from a voter” as “an unnatural and stilted conception of the actions taken by” election officials.","sumSrc":"brief:1","by":{"1":"5, 23–29","2":"21, 39"}},{"t":"case","label":"Miss. Pub. Serv. Comm’n v. Miss. Power & Light Co.","cite":"593 So. 2d 997","y":1991,"court":"Miss.","url":"https://www.courtlistener.com/c/So.%202d/593/997/","op":6,"by":{"1":"28"}},{"t":"case","label":"Moore v. Harper","cite":"600 U.S. 1","y":2023,"id":"2022/21-1271","sc":1,"sum":"The Federal Elections Clause does not vest exclusive and independent authority in state legislatures to set the rules regarding federal elections and therefore did not bar the North Carolina Supreme Court from reviewing the North Carolina Legislature’s congressional districting plans for compliance with North Carolina law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15, 20, 35"}},{"t":"case","label":"NAACP v. U.S. Postal Serv.","cite":"2020 WL 6469845","y":2020,"court":"D.D.C. Nov. 1","by":{"1":"31"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"586 U.S. 105","y":2019,"id":"2018/17-340","sc":1,"op":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17","2":"25","3":"30"}},{"t":"case","label":"Trump v. United States","cite":"603 U.S. 593","y":2024,"id":"2023/23-939","sc":1,"sum":"The nature of Presidential power entitles a former President to absolute immunity from criminal prosecution for actions within his conclusive and preclusive constitutional authority; he is also entitled to at least presumptive immunity from prosecution for all his official acts; there is no immunity for unofficial acts.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25, 31"}},{"t":"case","label":"Voting Integrity Project, Inc. v. Bomer","cite":"199 F.3d 773","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/199/773/","sum":"Upholding Texas early voting law, in part, because it was consistent with purposes of a uniform federal election day.","sumSrc":"brief:1","by":{"1":"5, 29–32","5":"14"}},{"t":"const","label":"Article I, Section 4","clauses":[["elections-clause","Elections Clause"]],"text":"The Times, Places and Manner of holding Elections for Senators and Representatives, shall be prescribed in each State by the Legislature thereof; but the Congress may at any time by Law make or alter such Regulations, except as to the Places of chusing Senators. The Congress shall assemble at least once in every Year, and such Meeting shall be on the first Monday in December, unless they shall by Law appoint a different Day.","by":{"1":"4, 9","2":"3, 13, 45"}},{"t":"const","label":"Article II, Section 1","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"]],"by":{"1":"4","2":"3, 45"}},{"t":"usc","label":"52 U.S.C. § 20303","url":"https://www.law.cornell.edu/uscode/text/52/20303","subs":["(b)(3)","(b)","(d)"],"stext":{"head":"§20303. Federal write-in absentee ballot in general elections for Federal office for absent uniformed services voters and overseas voters","paras":[[0,"(a) In general"],[0,"(1) Federal write-in absentee ballot"],[1,"The Presidential designee shall prescribe a Federal write-in absentee ballot (including a secrecy envelope and mailing envelope for such ballot) for use in general, special, primary, and runoff elections for Federal office by absent uniformed services voters and overseas voters who make timely application for, and do not receive, States,1 absentee ballots."],[0,"(2) Promotion and expansion of use of Federal write-in absentee ballots"],[0,"(A) In general"],[2,"Not later than December 31, 2011, the Presidential designee shall adopt procedures to promote and expand the use of the Federal write-in absentee ballot as a back-up measure to vote in elections for Federal office."],[0,"(B) Use of technology"],[2,"Under such procedures, the Presidential designee shall utilize technology to implement a system under which the absent uniformed services voter or overseas voter may—"],[3,"(i) enter the address of the voter or other information relevant in the appropriate jurisdiction of the State, and the system will generate a list of all candidates in the election for Federal office in that jurisdiction; and"],[3,"(ii) submit the marked Federal write-in absentee ballot by printing the ballot (including complete instructions for submitting the marked Federal write-in absentee ballot to the appropriate State election official and the mailing address of the single State office designated under section 20302(b) of this title)."],[0,"(C) Authorization of appropriations"],[2,"There are authorized to be appropriated to the Presidential designee such sums as may be necessary to carry out this paragraph."],[0,"(b) Submission and processing"],[0,"Except as otherwise provided in this chapter, a Federal write-in absentee ballot shall be submitted and processed in the manner provided by law for absentee ballots in the State involved. A Federal write-in absentee ballot of an absent uniformed services voter or overseas voter shall not be counted—"],[1,"(1) in the case of a ballot submitted by an overseas voter who is not an absent uniformed services voter, if the ballot is submitted from any location in the United States;"],[1,"(2) if the application of the absent uniformed services voter or overseas voter for a State absentee ballot is received by the appropriate State election official after the later of—"],[2,"(A) the deadline of the State for receipt of such application; or"],[2,"(B) the date that is 30 days before the general election; or"],[1,"(3) if a State absentee ballot of the absent uniformed services voter or overseas voter is received by the appropriate State election official not later than the deadline for receipt of the State absentee ballot under State law."],[0,"(c) Special rules"],[0,"The following rules shall apply with respect to Federal write-in absentee ballots:"],[1,"(1) In completing the ballot, the absent uniformed services voter or overseas voter may designate a candidate by writing in the name of the candidate or by writing in the name of a political party (in which case the ballot shall be counted for the candidate of that political party)."],[1,"(2) In the case of the offices of President and Vice President, a vote for a named candidate or a vote by writing in the name of a political party shall be counted as a vote for the electors supporting the candidate involved."],[1,"(3) Any abbreviation, misspelling, or other minor variation in the form of the name of a candidate or a political party shall be disregarded in determining the validity of the ballot, if the intention of the voter can be ascertained."],[0,"(d) Second ballot submission; instruction to absent uniformed services voter or overseas voter"],[0,"An absent uniformed services voter or overseas voter who submits a Federal write-in absentee ballot and later receives a State absentee ballot, may submit the State absentee ballot. The Presidential designee shall assure that the instructions for each Federal write-in absentee ballot clearly state that an absent uniformed services voter or overseas voter who submits a Federal write-in absentee ballot and later receives and submits a State absentee ballot should make every reasonable effort to inform the appropriate State election official that the voter has submitted more than one ballot."],[0,"(e) Use of approved State absentee ballot in place of Federal write-in absentee ballot"],[0,"The Federal write-in absentee ballot shall not be valid for use in a general, special, primary, or runoff election for Federal office if the State involved provides a State absentee ballot that—"],[1,"(1) at the request of the State, is approved by the Presidential designee for use in place of the Federal write-in absentee ballot; and"],[1,"(2) is made available to absent uniformed services voters and overseas voters at least 60 days before the deadline for receipt of the State ballot under State law."],[0,"(f) Prohibiting refusal to accept ballot for failure to meet certain requirements"],[0,"A State shall not refuse to accept and process any otherwise valid Federal write-in absentee ballot submitted in any manner by an absent uniformed services voter or overseas voter solely on the basis of the following:"],[1,"(1) Notarization requirements."],[1,"(2) Restrictions on paper type, including weight and size."],[1,"(3) Restrictions on envelope type, including weight and size."],[0,"(g) Certain States exempted"],[0,"A State is not required to permit use of the Federal write-in absentee ballot, if, on and after August 28, 1986, the State has in effect a law providing that—"],[1,"(1) a State absentee ballot is required to be available to any voter described in section 20310(5)(A) of this title at least 90 days before the general, special, primary, or runoff election for Federal office involved; and"],[1,"(2) a State absentee ballot is required to be available to any voter described in section 20310(5)(B) or (C) of this title, as soon as the official list of candidates in the general, special, primary, or runoff election for Federal office is complete."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20303?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§20303. Federal write-in absentee ballot in general elections for Federal office for absent uniformed services voters and overseas voters","tname":"Voting and Elections","by":{"1":"15, 44, 45, 48","2":"44","3":"42","4":"24, 24","5":"11"}},{"t":"usc","label":"52 U.S.C. § 20304","url":"https://www.law.cornell.edu/uscode/text/52/20304","subs":["(b)(1)"],"stext":{"head":"§20304. Procedures for collection and delivery of marked absentee ballots of absent overseas uniformed services voters","paras":[[0,"(a) Establishment of procedures"],[0,"The Presidential designee shall establish procedures for collecting marked absentee ballots of absent overseas uniformed services voters in regularly scheduled general elections for Federal office, including absentee ballots prepared by States and the Federal write-in absentee ballot prescribed under section 20303 of this title, and for delivering such marked absentee ballots to the appropriate election officials."],[0,"(b) Delivery to appropriate election officials"],[0,"(1) In general"],[1,"Under the procedures established under this section, the Presidential designee shall implement procedures that facilitate the delivery of marked absentee ballots of absent overseas uniformed services voters for regularly scheduled general elections for Federal office to the appropriate election officials, in accordance with this section, not later than the date by which an absentee ballot must be received in order to be counted in the election."],[0,"(2) Cooperation and coordination with the United States Postal Service"],[1,"The Presidential designee shall carry out this section in cooperation and coordination with the United States Postal Service, and shall provide expedited mail delivery service for all such marked absentee ballots of absent uniformed services voters that are collected on or before the deadline described in paragraph (3) and then transferred to the United States Postal Service."],[0,"(3) Deadline described"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), the deadline described in this paragraph is noon (in the location in which the ballot is collected) on the seventh day preceding the date of the regularly scheduled general election for Federal office."],[0,"(B) Authority to establish alternative deadline for certain locations"],[2,"If the Presidential designee determines that the deadline described in subparagraph (A) is not sufficient to ensure timely delivery of the ballot under paragraph (1) with respect to a particular location because of remoteness or other factors, the Presidential designee may establish as an alternative deadline for that location the latest date occurring prior to the deadline described in subparagraph (A) which is sufficient to provide timely delivery of the ballot under paragraph (1)."],[0,"(4) No postage requirement"],[1,"In accordance with section 3406 of title 39, such marked absentee ballots and other balloting materials shall be carried free of postage."],[0,"(5) Date of mailing"],[1,"Such marked absentee ballots shall be postmarked with a record of the date on which the ballot is mailed."],[0,"(c) Outreach for absent overseas uniformed services voters on procedures"],[0,"The Presidential designee shall take appropriate actions to inform individuals who are anticipated to be absent overseas uniformed services voters in a regularly scheduled general election for Federal office to which this section applies of the procedures for the collection and delivery of marked absentee ballots established pursuant to this section, including the manner in which such voters may utilize such procedures for the submittal of marked absentee ballots pursuant to this section."],[0,"(d) Absent overseas uniformed services voter defined"],[0,"In this section, the term \"absent overseas uniformed services voter\" means an overseas voter described in section 20310(5)(A) of this title."],[0,"(e) Authorization of appropriations"],[0,"There are authorized to be appropriated to the Presidential designee such sums as may be necessary to carry out this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/20304?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§20304. Procedures for collection and delivery of marked absentee ballots of absent overseas uniformed services voters","tname":"Voting and Elections","by":{"1":"15, 46","2":"44","3":"42","4":"24"}},{"t":"law","label":"Pub. L. No. 117-328","url":"https://www.govinfo.gov/link/plaw/117/public/328","by":{"1":"50","4":"27"}},{"t":"law","label":"Pub. L. No. 84-296","url":"https://www.govinfo.gov/link/statute/69/584","by":{"1":"45"}},{"t":"law","label":"MOVE Act, Pub. L. No. 111-84","url":"https://www.govinfo.gov/link/plaw/111/public/84","by":{"1":"46"}},{"t":"case","label":"Bost v. Ill. State Bd. of Elections","cite":"607 U.S. __","sc":1,"by":{"2":"10, 18"}},{"t":"case","label":"Busbee v. Smith","cite":"549 F. Supp. 494","y":1982,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./549/494/","by":{"2":"20"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42, 43"}},{"t":"case","label":"Crawford v. Marion Cnty. Election Bd.","cite":"553 U.S. 181","y":2008,"id":"2007/07-21","sc":1,"op":1,"sum":"By a vote of 6 to 3, the Court upheld the law, concluding that the photo I.D. requirement was closely related to Indiana's legitimate state interests in preventing voter fraud.","sumSrc":"Oyez","by":{"2":"47","4":"29"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"25"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"591 U.S. 894","y":2020,"id":"2019/18-9526","sc":1,"sum":"The Court held that parts of eastern Oklahoma are an Indian reservation subject to exclusive federal jurisdiction for certain crimes under the Indian Major Crimes Act.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"N.Y. State Rifle & Pistol Ass’n v. Bruen","cite":"597 U.S. 1","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/1/","sc":1,"by":{"2":"27, 29, 30, 36","3":"32"}},{"t":"case","label":"Nat’l Pork Producers Council v. Ross","cite":"598 U.S. 356","y":2023,"id":"2022/21-468","sc":1,"sum":"The judgment of the Court of Appeals for the Ninth Circuit—affirming the dismissal of a complaint challenging California’s Proposition 12 under a dormant Commerce Clause rationale not grounded in an allegation that the law purposefully discriminates against out-of-state economic interests—is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"41"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"2":"25, 45"}},{"t":"case","label":"Pub. Citizen, Inc. v. Miller","cite":"813 F. Supp. 821","y":1993,"court":"N.D. Ga.","url":"https://www.courtlistener.com/c/F.%20Supp./813/821/","by":{"2":"20"}},{"t":"case","label":"Purcell v. Gonzalez","cite":"549 U.S. 1","y":2006,"id":"2006/06-532","sc":1,"ar":2,"sum":"The Court decided that the U.S. Court of Appeals for the Ninth Circuit improperly granted an emergency injunction against the enforcement of Proposition 200.","sumSrc":"Oyez","by":{"2":"47","3":"44"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"2":"41","4":"27"}},{"t":"case","label":"Ray v. Blair","cite":"343 U.S. 214","y":1952,"id":"scdb/1951-069","sc":1,"sum":"Where a state authorizes a political party to choose its nominees for Presidential Electors in a state-controlled party primary election and to fix the qualifications for the candidates, it is not violative of the Federal Constitution for the party to require the candidates for the office of Presidential Elector to take a pledge to support the \"nominees of the party's National Convention for President,and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"Regions Bank v. Legal Outsource PA","cite":"936 F.3d 1184","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/936/1184/","by":{"2":"41"}},{"t":"case","label":"U.S. Term Limits, Inc. v. Thornton","cite":"514 U.S. 779","y":1995,"id":"1994/93-1456","sc":1,"op":1,"sum":"The Constitution prohibits States from adopting Congressional qualifications in addition to those enumerated in the Constitution.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"law","label":"Uniformed and Overseas Citizens Absentee Voting Act, Pub. L. No. 99-410","url":"https://www.govinfo.gov/link/statute/100/924","by":{"2":"43"}},{"t":"reg","label":"39 C.F.R. § 111.1","url":"https://www.ecfr.gov/current/title-39/section-111.1","by":{"2":"24"}},{"t":"reg","label":"39 C.F.R. § 211.2","url":"https://www.ecfr.gov/current/title-39/section-211.2","by":{"2":"24"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"3":"45"}},{"t":"case","label":"Bourland v. Hildreth","cite":"26 Cal. 161","y":1864,"url":"https://www.courtlistener.com/c/Cal./26/161/","by":{"3":"21"}},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"594 U.S. 647","y":2021,"id":"2020/19-1257","sc":1,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"37","4":"29"}},{"t":"case","label":"Cent. Bank of Denv. v. First Interstate Bank of Denv.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"3":"38"}},{"t":"case","label":"Cipollone v. Liggett Grp.","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Fish v. Kobach","cite":"840 F.3d 710","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/840/710/","by":{"3":"6"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"3":"35"}},{"t":"case","label":"J.E.M. Ag Supply v. Pioneer Hi-Bred Int’l","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"sum":"The Court held that utility patents may be issued for plants.","sumSrc":"Oyez","by":{"3":"40"}},{"t":"case","label":"Norman v. Thompson","cite":"72 S.W. 62","y":1903,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W./72/62/","op":1,"by":{"3":"21","4":"15","5":"7"}},{"t":"case","label":"People ex rel. Twitchell v. Blodgett","cite":"13 Mich. 127","y":1865,"url":"https://www.courtlistener.com/c/Mich./13/127/","by":{"3":"18, 22, 31","4":"10","5":"8"}},{"t":"case","label":"People v. Gagliardi","cite":"111 N.Y.S. 395","y":1908,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S./111/395/","by":{"3":"22"}},{"t":"case","label":"Petty v. Myers","cite":"49 Ind. 1","y":1874,"url":"https://www.courtlistener.com/c/Ind./49/1/","sum":"Stating that the county board “ordered an election, ‘for the purpose of taking the votes of the legal voters of the said township’” regarding an appropriation of funds for railroad construction.","sumSrc":"brief:3","by":{"3":"21"}},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"36"}},{"t":"case","label":"Sw. Airlines v. Saxon","cite":"596 U.S. 450","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/450/","sc":1,"by":{"3":"30"}},{"t":"case","label":"United States v. Price","cite":"361 U.S. 304","y":1960,"id":"1959/48","sc":1,"sum":"Under § 272 (a) (1) of the Internal Revenue Code of 1939, as amended, failure of the Commissioner of Internal Revenue to send to a taxpayer a 90-day notice of a deficiency in his income tax return does not bar an action by the United States to collect such deficiency and statutory interest thereon when the taxpayer had executed and filed, under § 272 (d), a waiver of the restrictions of § 272 (a) on the assessment …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"United States v. Pub. Util. Comm’n","cite":"345 U.S. 295","y":1943,"id":"scdb/1952-073","sc":1,"sum":"The rates for such sales of power for resale are subject to regulation by the Federal Power Commission under Part II of the Federal Power Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"37"}},{"t":"case","label":"Wisc. Cent. v. United States","cite":"585 U.S. 274","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/274/","sc":1,"by":{"3":"14"}},{"t":"const","label":"Amendment XII","text":"The Electors shall meet in their respective states and vote by ballot for President and Vice-President, one of whom, at least, shall not be an inhabitant of the same state with themselves; they shall name in their ballots the person voted for as President, and in distinct ballots the person voted for as Vice-President, and they shall make distinct lists of all persons voted for as President, and of all persons voted for as Vice-President, and of the number of votes for each, which lists they shall sign and certify, and transmit sealed to the seat of the government of the United States, directed to the President of the Senate; -- the President of the Senate shall, in the presence of the Senate and House of Representatives, open all the certificates and the votes shall then be counted; -- The person having the greatest number of votes for President, shall be the President, if such number be a majority of the whole number of Electors appointed; and if no person have such majority, then from the persons having the highest numbers not exceeding three on the list of those voted for as President, the House of Representatives shall choose immediately, by ballot, the President. But in choosing the President, the votes shall be taken by states, the representation from each state having one vote; a quorum for this purpose shall consist of a member or members from two-thirds of the states, and a majority of all the states shall be necessary to a choice. [And if the House of Representatives shall not choose a President whenever the right of choice shall devolve upon them, before the fourth day of March next following, then the Vice-President shall act as President, as in the case of the death or other constitutional disability of the President. --] The person having the greatest number of votes as Vice-President, shall be the Vice-President, if such number be a majority of the whole number of Electors appointed, and if no person have a majority, then from the two highest numbers on the list, the Senate shall choose the Vice-President; a quorum for the purpose shall consist of two-thirds of the whole number of Senators, and a majority of the whole number shall be necessary to a choice. But no person constitutionally ineligible to the office of President shall be eligible to that of Vice-President of the United States.","by":{"3":"4"}},{"t":"usc","label":"52 U.S.C. § 10308","url":"https://www.law.cornell.edu/uscode/text/52/10308","subs":["(b)"],"by":{"3":"43"}},{"t":"law","label":"Pub. L. No. 86-449","url":"https://www.govinfo.gov/link/statute/74/86","by":{"3":"43"}},{"t":"law","label":"Pub. L. No. 89-110","url":"https://www.govinfo.gov/link/statute/79/437","by":{"3":"43"}},{"t":"law","label":"Pub. L. No. 91-285","url":"https://www.govinfo.gov/link/statute/84/314","by":{"3":"41"}},{"t":"reg","label":"90 Fed. Reg. 52,883","url":"https://www.govinfo.gov/link/fr/90/52883","by":{"3":"33"}},{"t":"case","label":"A.T. & Sante Fe R.R. v. Commissioner of Jefferson County","cite":"17 Kan. 29","y":1876,"url":"https://www.courtlistener.com/c/Kan./17/29/","by":{"4":"16","5":"7, 9"}},{"t":"case","label":"Bostock v. Clayton County","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"4":"25"}},{"t":"case","label":"Burroughs v. Lyles","cite":"181 S.W.2d 570","y":1944,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/181/570/","by":{"4":"14"}},{"t":"case","label":"City of Inglewood v. Kew","cite":"132 P. 780","y":1913,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/P./132/780/","by":{"4":"10","5":"7"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"4":"27"}},{"t":"case","label":"New York State Rifle & Pistol Ass’n v. Bruen","cite":"597 U.S. 1","y":2022,"id":"2021/20-843","sc":1,"op":1,"sum":"New York’s proper-cause requirement for obtaining an unrestricted license to carry a concealed firearm violates the Fourteenth Amendment in that it prevents law-abiding citizens with ordinary self-defense needs from exercising their Second Amendment right to keep and bear arms.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"21"}},{"t":"case","label":"Oncale v. Sundowner Offshore Services, Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"4":"30"}},{"t":"case","label":"People ex. rel. Le Roy v. Foley","cite":"43 N.E. 171","y":1896,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./43/171/","ar":1,"by":{"4":"11","5":"7, 9"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"4":"25"}},{"t":"case","label":"Republican Party of Pennsylvania v. Degraffenreid","cite":"141 S. Ct. 732","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/732/","sc":1,"by":{"4":"29"}},{"t":"case","label":"State v. Tucker","cite":"54 Ala. 205","y":1875,"url":"https://www.courtlistener.com/c/Ala./54/205/","by":{"4":"10","5":"9"}},{"t":"case","label":"State ex rel. Runge v. Anderson","cite":"76 N.W. 482","y":1898,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W./76/482/","by":{"4":"10"}},{"t":"case","label":"United States v. Rahimi","cite":"602 U.S. 680","y":2024,"id":"2023/22-915","sc":1,"op":1,"sum":"When an individual has been found by a court to pose a credible threat to the physical safety of another, that individual may be temporarily disarmed consistent with the Second Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"23"}},{"t":"usc","label":"50 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/50/301","by":{"4":"23"}},{"t":"usc","label":"52 U.S.C. § 10301","url":"https://www.law.cornell.edu/uscode/text/52/10301","by":{"4":"26"}},{"t":"usc","label":"26 U.S.C. § 7502","url":"https://www.law.cornell.edu/uscode/text/26/7502","subs":["(a)"],"by":{"4":"14"}},{"t":"reg","label":"Exec. Order No. 14,248, 90 Fed. Reg. 14,005","url":"https://www.govinfo.gov/link/fr/90/14005","by":{"4":"1"}},{"t":"case","label":"Executive Benefits Insurance Agency v. Arkison","cite":"573 U.S. 25","y":2014,"id":"2013/12-1200","sc":1,"sum":"The Court found that a bankruptcy judge may hear arguments and file a report with a district court for \"non-core\" bankruptcy issues.","sumSrc":"Oyez","by":{"5":"19"}},{"t":"usc","label":"3 U.S.C. § 11","url":"https://www.law.cornell.edu/uscode/text/3/11","by":{"5":"20"}}]};